window.PLAZAS = [{"id": "@plaza-from-doc", "district_ref": "@dist-doc", "title": "From document to map", "subtitle": "", "description": "Three different kinds of source \u2014 a report chapter, a research paper, a project canvas \u2014 compiled by the same kit. Numbers are from the specs in this repository.", "row_axis": "source", "col_axis": "what it became", "rows": ["SCIANCE chapter", "arXiv paper", "KD canvas"], "cols": ["source", "districts", "buildings", "tour stops"], "layers": [{"id": "x", "label": "Three real sources and the maps compiled from them", "cells": [["14.5k words", 5, 16, "\u2014"], ["23k words", 5, 38, 9], ["24 nodes", 4, 18, "\u2014"]]}], "highlight": [], "hatch": [], "expected": false, "color": "#00f0ff", "corners": [[13.3973429, 52.5005057], [13.4046056, 52.5005057], [13.4046056, 52.4973167], [13.3973429, 52.4973167]], "frame": {"width_m": 492.0, "height_m": 355.0, "grid_x_m": 180.0, "grid_y_m": 84.0, "cell_m": 75.0}, "coordinates": [13.4022142, 52.4987406]}];

window.TOUR = [{"id": "doc", "title": "Nobody reads page 47", "text": "Reports, papers and project plans carry their argument in tables, caveats and page 47. These three were real, and each became a map.", "look": "The three sources and the 'from document to map' plaza", "focus": ["@spire-src-sciance", "@spire-src-paper", "@spire-src-kd", "@plaza-from-doc", "@chal-minutes"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "guide", "text": "[warm] Welcome to Explainopolis \u2014 a map that explains how it was made. I'm Maya, I'll be your guide.", "do": [{"show": "@dist-doc"}]}, {"speaker": "sceptic", "text": "[dryly] And I'm Owen. I'll ask what you would ask. So \u2014 why a map? What's wrong with the document?"}, {"speaker": "guide", "text": "[thoughtful] Nothing, except that nobody reads it. A report keeps its argument in tables, caveats and page forty-seven. These three are real: a materials-science chapter, an arXiv paper, and a CEO's project canvas.", "do": [{"highlight": ["@spire-src-sciance", "@spire-src-paper", "@spire-src-kd"]}]}, {"speaker": "sceptic", "text": "[skeptical] Three very different documents. One tool for all of them?"}, {"speaker": "guide", "text": "[confident] The same kit. This plaza is the evidence. The paper ran to about twenty-three thousand words; its map has thirty-eight buildings and a nine-stop tour.", "do": [{"show": "@plaza-from-doc"}, {"plaza_cell": {"plaza": "@plaza-from-doc", "row": "arXiv paper", "col": "buildings"}}]}, {"speaker": "sceptic", "text": "[dryly] The goal out there says minutes, not pages. Let's see you earn it.", "do": [{"highlight": ["@chal-minutes"]}]}], "quiz": [], "camera": {"center": [13.4, 52.4984711], "zoom": 15.1, "pitch": 52, "bearing": -12}}, {"id": "und", "title": "Agents read, a human approves", "text": "One agent proposes a one-page profile, another writes the spec. A person approves both, and a provenance file says where each number comes from.", "look": "Discovery \u2192 profile \u2192 architect \u2192 spec, and the review gate", "focus": ["@spire-discovery", "@spire-profile", "@spire-architect", "@spire-spec", "@spire-review", "@chal-trace", "@bneck-review", "@conduit-propose", "@conduit-approve", "@conduit-specify"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "sceptic", "text": "[skeptical] Let me guess. You paste the paper into a chatbot and it draws a city?"}, {"speaker": "guide", "text": "[amused] Not quite. A discovery agent reads the source and proposes how to map it \u2014 the axis, the districts, the landmarks \u2014 on a single page.", "do": [{"show": ["@spire-discovery", "@spire-profile"]}]}, {"speaker": "sceptic", "text": "And who checks that page?"}, {"speaker": "guide", "text": "[matter-of-fact] A person. That's the first gate, and it's cheap: you argue about one page before anything is built. Then an architect agent turns the approved profile into a city spec \u2014 what exists, what flows where, what blocks what. No coordinates.", "do": [{"highlight": ["@spire-profile", "@spire-architect", "@spire-spec", "@conduit-approve", "@conduit-specify"]}]}, {"speaker": "sceptic", "text": "[pointed] Agents write numbers. Agents get numbers wrong."}, {"speaker": "guide", "text": "[serious] Which is why the second gate is here: a human review, and a provenance file that separates what the source says, what we recounted, and what is only a choice of the map. On the paper's map it records the one place where the map follows the authors' own audit instead of the printed text.", "do": [{"show": ["@spire-review", "@spire-spec"]}]}, {"speaker": "sceptic", "text": "[dryly] So that red flag on the spec is a limit you admit, not a bug you hide.", "do": [{"highlight": ["@bneck-review", "@spire-spec"]}]}, {"speaker": "guide", "text": "[warm] Exactly. Every map here draws its limits where they act."}], "quiz": [{"ask": {"speaker": "sceptic", "text": "[dryly] Your turn. Show me where a human checks the agents' work."}, "answer": ["@spire-review", "@bneck-review", "@spire-profile"], "right": {"speaker": "guide", "text": "[pleased] Exactly. Agents draft, a person approves, and the provenance file keeps the receipts.", "do": [{"show": ["@spire-review", "@spire-profile"]}]}, "wrong": {"speaker": "guide", "text": "[gentle] Close. The gates are here: the one-page profile, and the human review with its provenance file.", "do": [{"show": ["@spire-review", "@spire-profile"]}]}}], "camera": {"center": [13.4, 52.5067355], "zoom": 15.1, "pitch": 52, "bearing": -12}}, {"id": "build", "title": "One spec, many views", "text": "A deterministic compiler turns the spec into a 3D city, a metro map and this tour. Change the spec, rebuild, and every view agrees.", "look": "Compiler \u2192 city, metro, tour", "focus": ["@spire-compiler", "@spire-city", "@spire-metro", "@spire-tour", "@spire-validator", "@chal-one-spec", "@conduit-city", "@conduit-metro", "@conduit-tour", "@conduit-compile"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "guide", "text": "[brisk] From here on, nothing is guessed. The compiler reads the spec, places every building, routes every road, and works out the cameras for this tour.", "do": [{"show": "@spire-compiler"}]}, {"speaker": "sceptic", "text": "[skeptical] Deterministic? Same spec, same city?"}, {"speaker": "guide", "text": "[confident] Same spec, same city. About fifteen hundred lines of plain Python. It refuses a spec with a broken reference, and every change is rendered headless before it ships.", "do": [{"highlight": ["@spire-compiler", "@spire-validator"]}]}, {"speaker": "sceptic", "text": "[honest] Still, this city is a lot. I'd lose my manager by district two."}, {"speaker": "guide", "text": "[playful] Then switch. Same spec, drawn as a metro map: one line per district, and the interchanges are where the story changes lines.", "do": [{"view": "metro"}, {"highlight": ["@spire-spec", "@spire-compiler", "@spire-metro"]}]}, {"speaker": "sceptic", "text": "[surprised] The same file? Not a second drawing?"}, {"speaker": "guide", "text": "[matter-of-fact] The same file. Click an interchange and it tells you why it's there. One spec, every view \u2014 that's the goal of this district.", "do": [{"highlight": ["@chal-one-spec", "@spire-city", "@spire-metro", "@spire-tour"]}]}, {"speaker": "sceptic", "text": "[dryly] And the catch?"}, {"speaker": "guide", "text": "[candid] Big districts still need positions by hand. It's marked, right there on the compiler.", "do": [{"view": "city"}, {"show": ["@spire-compiler", "@bneck-layout"]}]}], "quiz": [], "camera": {"center": [13.4, 52.515], "zoom": 15.1, "pitch": 52, "bearing": -12}}, {"id": "voice", "title": "The map talks \u2014 and listens", "text": "deckcast voices the script with two speakers. The tour is a dialogue, the map asks you a question, and a live agent answers yours.", "look": "deckcast, the handover files, and three levels of voice", "focus": ["@spire-deckcast", "@spire-narration", "@spire-cues", "@spire-level1", "@spire-level2", "@spire-level3", "@chal-ask", "@conduit-voice", "@conduit-cues", "@conduit-play", "@conduit-qa", "@conduit-kb"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "sceptic", "text": "[dryly] Here's my real question. Who is talking right now?"}, {"speaker": "guide", "text": "[amused] We are \u2014 but neither of us was recorded. This conversation is a script in the same spec, and deckcast turned it into voices.", "do": [{"show": ["@spire-deckcast", "@spire-narration"]}]}, {"speaker": "sceptic", "text": "[curious] deckcast being?"}, {"speaker": "guide", "text": "[brisk] A small tool that compiles a narration script into voiced clips, caches them, and times every line. Those timings are why the map moves exactly when I say \u2014 here.", "do": [{"highlight": ["@spire-cues", "@conduit-cues", "@spire-deckcast"]}]}, {"speaker": "sceptic", "text": "[impressed, grudging] Neat. So this tour is level one. What are two and three?", "do": [{"highlight": ["@spire-level1", "@spire-level2", "@spire-level3"]}]}, {"speaker": "guide", "text": "[excited] Level two: the map asks you \u2014 you've met it already \u2014 and you answer with a click. Level three: you simply ask, out loud, and an agent answers from the map's own knowledge and flies the camera for you.", "do": [{"show": ["@spire-level2", "@spire-level3"]}]}, {"speaker": "sceptic", "text": "[skeptical] A live agent in a live demo. What could possibly go wrong."}, {"speaker": "guide", "text": "[candid] The network. That's why it's marked as a limit \u2014 and why levels one and two need no live connection at all.", "do": [{"highlight": ["@bneck-network", "@spire-level3"]}]}], "quiz": [], "camera": {"center": [13.4, 52.5232645], "zoom": 15.1, "pitch": 52, "bearing": -12}}, {"id": "use", "title": "Already working", "text": "Two public maps, a private CEO view and two narrated decks exist today \u2014 and this map was built the same way.", "look": "The live maps and decks", "focus": ["@spire-use-sciance", "@spire-use-paper", "@spire-use-kd", "@spire-use-decks"], "items": [], "plaza_layers": {}, "do": [], "dialogue": [{"speaker": "sceptic", "text": "[serious] Last question, and it's the one a jury asks. Is anyone actually using this?"}, {"speaker": "guide", "text": "[confident] Yes. The materials-science chapter and the arXiv paper are public maps you can open today.", "do": [{"show": ["@spire-use-sciance", "@spire-use-paper"]}]}, {"speaker": "sceptic", "text": "And the third one?"}, {"speaker": "guide", "text": "[matter-of-fact] A CEO's view of a live project. Private, because it names people and risks \u2014 same kit, kept local.", "do": [{"highlight": ["@spire-use-kd"]}]}, {"speaker": "sceptic", "text": "And deckcast?"}, {"speaker": "guide", "text": "Two decks narrated end to end, one with a link where you can talk to the agent.", "do": [{"highlight": ["@spire-use-decks"]}]}, {"speaker": "sceptic", "text": "[warmer] So the thing explaining itself is built exactly like the things it explains."}, {"speaker": "guide", "text": "[warm] That's the point. One spec, a compiler and a script \u2014 and a document nobody reads becomes a place you can walk through. And a place you can ask \u2014 press Ask, and talk to me.", "do": [{"show": "@dist-use"}]}], "quiz": [], "camera": {"center": [13.4, 52.5315289], "zoom": 15.1, "pitch": 52, "bearing": -12}}];

